INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (21, 'rank_math_description', 'এক নজরে বাংলা ১ম পত্র গদ্যাংশ সৃজনশীল প্রস্তুতি ২০২৬-২০২৭: (SSC Bangla 1st Paper Prose Part 1 Creative Questions & Answers 2027) এসএসসি ও দাখিল বাংলা ১ম পত্রের সর্বশেষ ১০০ নম্বরের মানবণ্টন অনুযায়ী খ-বিভাগে গদ্যাংশ থেকে ৪টি সৃজনশীল প্রশ্ন থাকে, যেখান থেকে বাধ্যতামূলকভাবে ন্যূনতম ২টি প্রশ্নের উত্তর দিতে হয় (মান: ১০ × ২ = ২০ নম্বর)।');
