INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (60, 'rank_math_description', 'রাষ্ট্র কি শুধুই শাসন করার জন্য? নাকি নাগরিকদের ভালো-মন্দ দেখার দায়িত্বও তার? প্রাচীনকালে রাষ্ট্র ছিল কেবলই একটি পুলিশি ব্যবস্থা, যার কাজ ছিল শুধু আইন-শৃঙ্খলা রক্ষা করা।');
