INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (62, 'rank_math_description', 'বাংলাদেশে শিল্প জাতীয়করণের ইতিহাস, পটভূমি, সমস্যা ও প্রভাব (২০২৬) বিভাগ: বাংলাদেশ অর্থনীতি ও শিল্পায়ন | সর্বশেষ সংস্করণ: ২০২৬ | বিসিএস ও অনার্স স্পেশাল সারসংক্ষেপ (Quick Overview): বাংলাদেশে শিল্প জাতীয়করণ (Industrial Nationalization in Bangladesh) হলো ১৯৭১ সালে মহান মুক্তিযুদ্ধের মাধ্যমে স্বাধীনতা অর্জনের পর ২৬ মার্চ ১৯৭২ তারিখে জারিকৃত ঐতিহাসিক ‘বাংলাদেশ শিল্পপ্রতিষ্ঠান (জাতীয়করণ) আদেশ’ (রাষ্ট্রপতির আদেশ নং ২৭/১৯৭২)-এর মাধ্যমে দেশের প্রায় ৮৫% বৃহৎ শিল্প-কারখানা রাষ্ট্রীয় মালিকানায় গ্রহণ করার নীতি।');
