INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (65, 'rank_math_description', 'সারসংক্ষেপ (Quick Overview): জনসংখ্যা পরিবর্তন (Population Dynamics) বলতে কোনো নির্দিষ্ট ভৌগোলিক অঞ্চলে সময়ের ব্যবধানে জনসংখ্যার আকার, কাঠামো ও ঘনত্বের হ্রাস-বৃদ্ধিকে বোঝায়।');
