INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (68, 'rank_math_description', 'পৃথিবী একটাই, আর এর সম্পদও সীমিত। কিন্তু যখন এই সীমিত সম্পদের ওপর অতিরিক্ত জনসংখ্যার চাপ পড়ে, তখন প্রকৃতির ভারসাম্য নষ্ট হতে শুরু করে।');
