INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (69, 'rank_math_description', 'মানুষের পরিচয় তার সংস্কৃতিতে। আমরা পহেলা বৈশাখে পান্তা-ইলিশ খাই কিংবা একুশে ফেব্রুয়ারিতে প্রভাতফেরিতে যাই—এ সবই আমাদের সংস্কৃতির অবিচ্ছেদ্য অংশ।');
