INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (71, 'rank_math_description', 'রাজনৈতিক অর্থনীতি কাকে বলে? সংজ্ঞা, পরিধি ও তাত্ত্বিক কাঠামো (২০২৬) বিভাগ: রাষ্ট্রবিজ্ঞান ও অর্থনীতি | সর্বশেষ সংস্করণ: ২০২৬ | অনার্স ও মাস্টার্স বিশেষ গাইড সারসংক্ষেপ (Quick Overview): রাজনৈতিক অর্থনীতি (Political Economy) হলো সমাজবিজ্ঞানের একটি গুরুত্বপূর্ণ আন্তঃশাস্ত্রীয় শাখা, যা রাষ্ট্রীয় রাজনৈতিক ক্ষমতা, শাসনব্যবস্থা ও আইনের সাথে অর্থনৈতিক বাজার, সম্পদ বণ্টন ও বাণিজ্যের গভীর পারস্পরিক সম্পর্ক অনুসন্ধান করে।');
