INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (72, 'rank_math_description', 'সারসংক্ষেপ (Quick Overview): জাতীয় সংসদে নারীদের সংরক্ষিত আসন হলো গণপ্রজাতন্ত্রী বাংলাদেশের সংবিধানের ৬৫(৩) অনুচ্ছেদ অনুযায়ী নারী সমাজের রাজনৈতিক ক্ষমতায়ন ও আইনসভায় প্রত্যক্ষ অংশগ্রহণ নিশ্চিত করার জন্য সংরক্ষিত ৫০টি সংসদীয় আসন।');
