INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (74, 'rank_math_description', 'সারসংক্ষেপ (Quick Overview): পুরুষতন্ত্র (Patriarchy) হলো এমন একটি সামাজিক, অর্থনৈতিক ও প্রাতিষ্ঠানিক ব্যবস্থা যেখানে পুরুষ সামাজিক মর্যাদা, সিদ্ধান্ত গ্রহণের ক্ষমতা, অর্থনৈতিক নিয়ন্ত্রণ এবং পারিবারিক কর্তৃত্বের ক্ষেত্রে একচ্ছত্র প্রাধান্য বিস্তার করে।');
