INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (75, 'rank_math_description', 'সারসংক্ষেপ: রাষ্ট্রবিজ্ঞান ও সমাজবিজ্ঞানের দৃষ্টিতে ‘রাজনীতিতে নারীর অংশগ্রহণ’ (Women’s Political Participation) বলতে কেবল ভোটাধিকার প্রয়োগ করাকে বোঝায় না; বরং আইন প্রণয়ন, রাষ্ট্র পরিচালনা, রাজনৈতিক দলের শীর্ষ সিদ্ধান্ত গ্রহণ, নির্বাচনে প্রত্যক্ষ প্রতিদ্বন্দ্বিতা এবং জনগুরুত্বপূর্ণ নীতি নির্ধারণ প্রক্রিয়ায় নারীর সম-অধিকার ও সক্রিয় ভূমিকাকে বোঝায়।');
