INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (116, 'rank_math_description', 'সাম্প্রতিক কালের রাষ্ট্রচিন্তা বলতে কী বুঝ: জাতীয়তাবাদ ও বিবর্তন (২০২৬) বিভাগ: মাস্টার্স রাষ্ট্রবিজ্ঞান | সর্বশেষ সংস্করণ: ২০২৬ | চূড়ান্ত স্পেশাল হ্যান্ডনোট সারসংক্ষেপ (Quick Overview): সাম্প্রতিক কালের রাষ্ট্রচিন্তা (Recent Political Thought) বলতে দ্বিতীয় বিশ্বযুদ্ধ পরবর্তী সময় থেকে শুরু করে বর্তমান একবিংশ শতাব্দী পর্যন্ত বিশ্ব রাজনীতিতে আবির্ভূত নতুন দার্শনিক ও বাস্তববাদী মতবাদগুলোকে বোঝায়।');
