INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (121, 'rank_math_description', 'সারসংক্ষেপ (Quick Overview): এসএসসি পরীক্ষার নির্দেশিকা (SSC Exam Instructions) হলো মাধ্যমিক ও উচ্চমাধ্যমিক শিক্ষা বোর্ড কর্তৃক জারিকৃত একগুচ্ছ বাধ্যতামূলক নিয়ম ও আচরণবিধি যা প্রতিটি পরীক্ষার্থীকে পরীক্ষার হলে অক্ষরে অক্ষরে পালন করতে হয়।');
