INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (126, 'rank_math_description', 'পবিত্র কুরআনের সূরা আল-আহযাবের ৫৬ নম্বর আয়াতে মহান আল্লাহ রাব্বুল আলামিন স্বয়ং নির্দেশ দিয়েছেন— “নিশ্চয়ই আল্লাহ ও তাঁর ফেরেশতাগণ নবীর ওপর সালাত (দরূদ) পেশ করেন।');
