INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (127, 'rank_math_description', 'বিশ্বনবী হযরত মুহাম্মাদ মুস্তফা সাল্লাল্লাহু আলাইহি ওয়া সাল্লামের শানে রচিত সালাত ও সালামের যত ক্বাসিদা রয়েছে, তার মধ্যে ‘সালাতুন ইয়া রাসুলুল্লাহ আলাইকুম, সালামুন ইয়া হাবীবাল্লাহ আলাইকুম’ বাংলা ভাষাভাষী অঞ্চলে শতাব্দীর পর শতাব্দী ধরে সবচেয়ে জনপ্রিয় ও ভক্তিপূর্ণ এক চিরন্তন নাতিয়া ক্বাসিদা।');
